const BIOGRAFIAS = {"homero":{"name":"Homer","dates":"8th century BC","born":-750,"died":-700,"place":"","role":"Greek epic poet","idea":"His epic poems fixed the Greek image of the gods and heroes, and were the basis of education and of the mythical thought that preceded philosophy.","obras":["Iliad","Odyssey"],"fuente":"Life of Homer attributed to Herodotus; Contest of Homer and Hesiod; Heraclitus, fragment on Homer and the lice","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-presocraticos"]},"hesiodo":{"name":"Hesiod","dates":"fl. c. 700 BC","born":-740,"died":-670,"place":"Ascra (Boeotia)","role":"Greek poet","idea":"He narrated the origin of the world and of the gods as a genealogy starting from Chaos, the great model of mythical explanation against which philosophy would be born.","obras":["Theogony","Works and Days"],"fuente":"Hesiod, Works and Days; Contest of Homer and Hesiod","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-presocraticos"]},"tales":{"name":"Thales of Miletus","dates":"c. 624 – c. 546 BC","born":-624,"died":-546,"place":"Miletus (Ionia, present-day Turkey)","role":"Presocratic philosopher","idea":"Considered the first philosopher, he sought a natural principle common to all things, the arkhé, and claimed that this principle is water.","obras":[],"fuente":"Aristotle, Politics I","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t1","fil-metafisica","fil-presocraticos","fil-grandes-preguntas"]},"anaximandro":{"name":"Anaximander","dates":"c. 610 – c. 546 BC","born":-610,"died":-546,"place":"Miletus (Ionia, present-day Turkey)","role":"Presocratic philosopher","idea":"The principle of all things is no concrete element, but the apeiron, something unlimited and indeterminate from which opposites arise and to which they return.","obras":[],"fuente":"Cicero, On Divination I","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-presocraticos"]},"anaximenes":{"name":"Anaximenes","dates":"c. 586 – c. 528 BC","born":-586,"died":-528,"place":"Miletus (Ionia, present-day Turkey)","role":"Presocratic philosopher","idea":"The principle of everything is air, which by rarefaction becomes fire and by condensation turns into wind, clouds, water, earth and stone.","obras":[],"block":"ant","subjects":["fil"],"temas":["fil-metafisica","fil-presocraticos"]},"pitagoras":{"name":"Pythagoras of Samos","dates":"c. 570 – c. 495 BC","born":-570,"died":-495,"place":"Samos (Greece)","role":"Presocratic philosopher and mathematician","idea":"The essence of reality is number: the universe is a harmonious, mathematical order, and the immortal soul must purify itself through successive reincarnations.","obras":[],"fuente":"Xenophanes, fragment quoted by Diogenes Laertius, Lives VIII","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t1","fil-presocraticos"]},"jenofanes":{"name":"Xenophanes of Colophon","dates":"c. 570 – c. 475 BC","born":-570,"died":-475,"place":"Colophon (Ionia, present-day Turkey)","role":"Presocratic poet and philosopher","idea":"Each people imagines the gods in its own image; against that anthropomorphism, he proposed a single god who resembles mortals neither in form nor in thought.","obras":["Elegies (fragments)","Silloi (fragments)"],"fuente":"Aristotle, Rhetoric II","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-presocraticos","fil-grandes-preguntas"]},"heraclito":{"name":"Heraclitus of Ephesus","dates":"c. 540 – c. 480 BC","born":-540,"died":-480,"place":"Ephesus (Ionia, present-day Turkey)","role":"Presocratic philosopher","idea":"Everything flows and nothing remains: reality is incessant change, born of the struggle of opposites but governed by a common rational logos or law.","obras":["On Nature (fragments)"],"fuente":"Aristotle, Parts of Animals I","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-metafisica","fil-presocraticos","fil-grandes-preguntas"]},"parmenides":{"name":"Parmenides of Elea","dates":"c. 515 – c. 450 BC","born":-515,"died":-450,"place":"Elea (Magna Graecia, present-day Italy)","role":"Presocratic philosopher","idea":"Being is and non-being is not: what is real is one, eternal and unmoving, and the change shown by the senses is mere appearance.","obras":["On Nature (poem, fragments)"],"fuente":"Plutarch, Against Colotes; Strabo, Geography VI; Diogenes Laertius, Lives IX","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-metafisica","fil-presocraticos","fil-grandes-preguntas","fil-montaigne-ensayos"]},"anaxagoras":{"name":"Anaxagoras of Clazomenae","dates":"c. 500 – 428 BC","born":-500,"died":-428,"place":"Clazomenae (Ionia, present-day Turkey)","role":"Presocratic philosopher","idea":"Everything is made of infinite seeds mixed together, and an intelligence, the Nous, set in motion the vortex that separated and ordered the cosmos.","obras":["On Nature (fragments)"],"fuente":"Diogenes Laertius, Lives II; Aristotle, Eudemian Ethics I","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-presocraticos"]},"empedocles":{"name":"Empedocles of Acragas","dates":"c. 495 – c. 435 BC","born":-495,"died":-435,"place":"Acragas (Sicily)","role":"Presocratic philosopher","idea":"Everything is composed of four eternal roots, earth, water, air and fire, which Love unites and Strife separates in an endless cosmic cycle.","obras":["On Nature (fragments)","Purifications (fragments)"],"fuente":"Diogenes Laertius, Lives VIII","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-metafisica","fil-presocraticos"]},"zenon_elea":{"name":"Zeno of Elea","dates":"c. 490 – c. 430 BC","born":-490,"died":-430,"place":"Elea (Magna Graecia)","role":"Eleatic philosopher","idea":"If one admits that there are many things and that there is motion, one falls into contradictions; hence Parmenides is right: being is one and motionless.","obras":[],"block":"ant","subjects":["fil"],"temas":["fil-metafisica","fil-presocraticos"]},"protagoras":{"name":"Protagoras of Abdera","dates":"c. 485 – c. 411 BC","born":-485,"died":-411,"place":"Abdera (Thrace, present-day Greece)","role":"Greek sophist","idea":"Man is the measure of all things: there are no absolute truths or values, only what seems true or just to each person or community.","obras":["On the Gods (fragments)","Truth (fragments)"],"fuente":"Aulus Gellius, Attic Nights V; Diogenes Laertius, Lives IX","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t2","fil-t3","fil-grandes-preguntas"]},"gorgias":{"name":"Gorgias of Leontini","dates":"c. 485 – c. 380 BC","born":-485,"died":-380,"place":"Leontini (Sicily)","role":"Sophist and teacher of rhetoric","idea":"Nothing exists, and if it did it could not be known or communicated; therefore language does not express what things are, but is a powerful instrument of persuasion.","obras":["On Non-Being (summaries)","Encomium of Helen","Defence of Palamedes"],"fuente":"Philostratus, Lives of the Sophists I; Plato, Gorgias; Pausanias, Description of Greece X","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-t4"]},"leucipo":{"name":"Leucippus","dates":"fl. c. 440 BC","born":-480,"died":null,"place":"Miletus or Abdera (not known for certain)","role":"Atomist philosopher","idea":"Everything is made of indivisible atoms moving in the void, and nothing happens by chance: everything occurs for a reason and by necessity.","obras":["The Great World-System (attributed)","On Intellect"],"block":"ant","subjects":["fil"],"temas":["fil-presocraticos"]},"policleto":{"name":"Polykleitos","dates":"5th century BC","born":-480,"died":-420,"place":"Argos (Peloponnese)","role":"Greek sculptor","idea":"The beauty of the human body depends on exact proportions between its parts, which can be measured, fixed in a rule and taught.","obras":["Canon (lost treatise)","Doryphoros (c. 440 BC)"],"fuente":"Aelian, Historical Miscellany XIV","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t7","fil-grandes-preguntas"]},"socrates":{"name":"Socrates","dates":"470/469 – 399 BC","born":-470,"died":-399,"place":"Athens","role":"Greek philosopher","idea":"Whoever truly knows the good acts well; that is why the philosophical task is to examine one’s own life and to seek, through dialogue, universal definitions.","obras":[],"fuente":"Plato, Apology of Socrates; Xenophon, Apology","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-t1","fil-t3","fil-metafisica","fil-t4","fil-t5","fil-t7","fil-presocraticos","fil-helenismo","fil-grandes-preguntas","fil-comunidades-perseguidos","fil-montaigne-ensayos"]},"democrito":{"name":"Democritus of Abdera","dates":"c. 460 – c. 370 BC","born":-460,"died":-370,"place":"Abdera (Thrace)","role":"Presocratic atomist philosopher","idea":"Everything that exists is made of indivisible atoms moving in the void; their collisions and combinations explain all the changes in nature.","obras":[],"fuente":"Seneca, On Anger II; Pseudo-Hippocratic Letters","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t2","fil-metafisica","fil-presocraticos","fil-grandes-preguntas"]},"aristipo":{"name":"Aristippus of Cyrene","dates":"c. 435 – c. 356 BC","born":-435,"died":-356,"place":"Cyrene (present-day Libya)","role":"Socratic hedonist philosopher","idea":"Pleasure is the only good and the end of life; one must enjoy present pleasure without letting oneself be mastered by it.","obras":[],"fuente":"Vitruvius, De architectura VI (preface)","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-helenismo"]},"platon":{"name":"Plato","dates":"c. 427 – 347 BC","born":-427,"died":-347,"place":"Athens","role":"Greek philosopher","idea":"True reality is the Ideas, eternal and unchanging, which only reason grasps; the sensible world we perceive is merely their imperfect copy.","obras":["Republic","Phaedo","Symposium","Phaedrus"],"fuente":"Diogenes Laertius, Lives III","tradicion":true,"vida":[{"a":-399,"t":"Trial and death of Socrates, his teacher"},{"a":-388,"b":-361,"t":"Journeys to Sicily (Syracuse)"},{"a":-387,"t":"Founds the Academy in Athens"},{"a":-380,"b":-370,"t":"Writes the Republic"}],"block":"ant","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t3","fil-metafisica","fil-t4","fil-t5","fil-t6","fil-t7","fil-presocraticos","fil-helenismo","fil-grandes-preguntas","fil-comunidades-perseguidos","fil-montaigne-ensayos"]},"diogenes":{"name":"Diogenes of Sinope","dates":"c. 412 – 323 BC","born":-412,"died":-323,"place":"Sinope (present-day Turkey)","role":"Cynic philosopher","idea":"To be free and happy one must need the minimum, live in accordance with nature and despise social conventions, wealth and power.","obras":[],"fuente":"Diogenes Laertius, Lives VI","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t1","fil-utilidad","fil-presocraticos","fil-helenismo"]},"aristoteles":{"name":"Aristotle","dates":"384 – 322 BC","born":-384,"died":-322,"place":"Stagira (Macedonia)","role":"Greek philosopher and scientist","idea":"Reality lies in concrete substances, composed of matter and form; happiness consists in realising our rational nature through virtue and life in community.","obras":["Metaphysics","Nicomachean Ethics","Politics","On the Soul"],"fuente":"Aelian, Historical Miscellany III; ancient biographies of Aristotle","tradicion":true,"vida":[{"a":-367,"b":-347,"t":"Student at Plato’s Academy"},{"a":-343,"b":-340,"t":"Educates Alexander the Great"},{"a":-335,"t":"Founds the Lyceum in Athens"},{"a":-323,"t":"Flees Athens"}],"block":"ant","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t3","fil-metafisica","fil-t4","fil-t5","fil-t6","fil-t7","fil-presocraticos","fil-helenismo","fil-grandes-preguntas","fil-comunidades-perseguidos","fil-montaigne-ensayos"]},"pirron":{"name":"Pyrrho of Elis","dates":"c. 360 – c. 270 BC","born":-360,"died":-270,"place":"Elis (Peloponnese)","role":"Sceptic philosopher","idea":"To every claim another equally convincing one can be opposed; that is why the sage suspends judgement and thus attains tranquillity of soul.","obras":[],"fuente":"Diogenes Laertius, Lives IX","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-t3","fil-montaigne-ensayos"]},"epicuro":{"name":"Epicurus","dates":"341 – 270 BC","born":-341,"died":-270,"place":"Samos","role":"Greek Hellenistic philosopher","idea":"Happiness is pleasure understood as the absence of pain in the body and of disturbance in the soul, achieved through moderation, friendship and freedom from fears.","obras":["Letter to Menoeceus","Letter to Herodotus","Principal Doctrines"],"fuente":"Seneca, Letters to Lucilius 21; Diogenes Laertius, Lives X","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-metafisica","fil-t5","fil-presocraticos","fil-helenismo","fil-grandes-preguntas","fil-comunidades-perseguidos","fil-montaigne-ensayos"]},"zenon":{"name":"Zeno of Citium","dates":"c. 334 – c. 262 BC","born":-334,"died":-262,"place":"Citium (Cyprus)","role":"founding philosopher of Stoicism","idea":"The universe is ordered by a divine reason; the sage accepts fate, masters his passions and is concerned only with what depends on him.","obras":[],"fuente":"Diogenes Laertius, Lives VII","tradicion":true,"block":"ant","subjects":["fil"],"temas":["fil-helenismo"]},"ciceron":{"name":"Marcus Tullius Cicero","dates":"106 – 43 BC","born":-106,"died":-43,"place":"Arpinum (Lazio, Italy)","role":"Roman orator, politician and philosopher","idea":"Greek philosophy can be thought in Latin: Cicero translated it for the Romans and presented the schools as a debate in which the reader has to decide.","obras":["On the Republic","Tusculan Disputations","On the Nature of the Gods","On Duties"],"fuente":"Plutarch, Life of Cicero 47-49","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-t1"]},"seneca":{"name":"Seneca","dates":"c. 4 BC – AD 65","born":-4,"died":65,"place":"Cordoba (Hispania)","role":"Roman Stoic philosopher","idea":"We do not control what happens to us, but we do control how we face it; wisdom consists in mastering the passions and making good use of the time of one’s life.","obras":["Letters to Lucilius","On the Shortness of Life","On Anger","On the Happy Life"],"fuente":"Seneca, On Anger III","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-helenismo","fil-montaigne-ensayos"]},"plotino":{"name":"Plotinus","dates":"205 – 270","born":205,"died":270,"place":"Lycopolis (Egypt)","role":"Neoplatonist philosopher","idea":"All reality proceeds from the One by necessary emanation, in decreasing degrees of perfection, and the soul can return to it through contemplation and purification.","obras":["Enneads"],"fuente":"Porphyry, Life of Plotinus","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-t7"]},"agustin":{"name":"Augustine of Hippo","dates":"354 – 430","born":354,"died":430,"place":"Thagaste (present-day Algeria)","role":"Christian philosopher and theologian","idea":"Truth is sought not outside but within the soul, where God illuminates it; faith guides reason so that it may understand.","obras":["Confessions (c. 397–400)","The City of God (413–426)","On the Trinity","On Free Will"],"fuente":"Augustine of Hippo, Confessions VIII","tradicion":false,"vida":[{"a":373,"b":383,"t":"Manichaean period"},{"a":384,"b":386,"t":"In Milan, with Ambrose"},{"a":386,"t":"Conversion"},{"a":387,"t":"Baptism"},{"a":395,"b":430,"t":"Bishop of Hippo"}],"block":"med","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-metafisica","fil-t6","fil-t7","fil-grandes-preguntas","fil-montaigne-ensayos"]},"hipatia":{"name":"Hypatia of Alexandria","dates":"c. 355/370 – AD 415","born":355,"died":415,"place":"Alexandria (Egypt)","role":"mathematician, astronomer and philosopher","idea":"She united Neoplatonic philosophy with the teaching of mathematics and astronomy, understanding the rational study of the cosmos as a path to wisdom.","obras":[],"fuente":"Damascius, Life of Isidore (fragments in the Suda); Socrates Scholasticus, Ecclesiastical History VII","tradicion":false,"block":"ant","subjects":["fil"],"temas":["fil-t3","fil-t1-filosofia-mujer","fil-comunidades-perseguidos"]},"boecio":{"name":"Boethius","dates":"c. 480 – 524","born":480,"died":524,"place":"Rome","role":"Roman philosopher and politician","idea":"True happiness does not lie in the goods of fortune, which come and go, but in the perfect good, which is God: if there are imperfect goods, there must be a perfect one.","obras":["The Consolation of Philosophy (around 524)","Translations of and commentaries on Aristotle’s logic","Commentaries on Porphyry’s Introduction"],"fuente":"Boethius, The Consolation of Philosophy I, proses 1 and 3","tradicion":false,"block":"med","subjects":["fil"],"temas":["fil-t2","fil-comunidades-perseguidos"]},"avicena":{"name":"Avicenna","dates":"980 – 1037","born":980,"died":1037,"place":"Afshana, near Bukhara (present-day Uzbekistan)","role":"Persian philosopher and physician","idea":"In all created things, what they are (essence) is distinguished from the fact that they exist (existence); only in God do the two coincide: He is the necessary being.","obras":["Canon of Medicine","Book of Healing"],"fuente":"Avicenna, Autobiography","tradicion":false,"block":"med","subjects":["fil"],"temas":["fil-metafisica"]},"anselmo":{"name":"Anselm of Canterbury","dates":"1033 – 1109","born":1033,"died":1109,"place":"Aosta (Italy)","role":"Scholastic philosopher and theologian","idea":"God is that than which nothing greater can be thought; therefore He cannot exist only in the mind, but must also exist in reality.","obras":["Monologion (1076)","Proslogion (1077–1078)","Why God Became Man"],"fuente":"Eadmer, Life of Saint Anselm","tradicion":false,"block":"med","subjects":["fil"],"temas":["fil-metafisica","fil-grandes-preguntas"]},"hildegarda":{"name":"Hildegard of Bingen","dates":"1098 – 1179","born":1098,"died":1179,"place":"Bermersheim (Rhineland, Germany)","role":"abbess, mystic and composer","idea":"The human being is a microcosm that reflects the order of the universe created by God, so that faith, natural science and art form a single body of knowledge.","obras":["Scivias (1141–1151)","Physica","Causes and Cures","Ordo Virtutum"],"fuente":"Hildegard’s letter to the prelates of Mainz; Life of Saint Hildegard","tradicion":false,"vida":[{"a":1141,"b":1151,"t":"Writes Scivias"},{"a":1158,"b":1163,"t":"Writes Liber vitae meritorum"},{"a":1163,"b":1174,"t":"Writes Liber divinorum operum"}],"block":"med","subjects":["fil"],"temas":["fil-grandes-preguntas"]},"averroes":{"name":"Averroes","dates":"1126 – 1198","born":1126,"died":1198,"place":"Cordoba (al-Andalus)","role":"Andalusian philosopher, jurist and physician","idea":"Truth cannot contradict truth: philosophical demonstration and revelation coincide, although each addresses a different kind of person.","obras":["Decisive Treatise","The Incoherence of the Incoherence","Commentaries on Aristotle","Book of Generalities of Medicine"],"fuente":"Al-Marrakushi, History of the Almohads (Kitab al-Mu‘jib)","tradicion":false,"block":"med","subjects":["fil"],"temas":["fil-grandes-preguntas","fil-comunidades-perseguidos","fil-montaigne-ensayos"]},"maimonides":{"name":"Maimonides","dates":"1138 – 1204","born":1138,"died":1204,"place":"Cordoba (al-Andalus)","role":"philosopher, physician and rabbi","idea":"Faith and reason do not contradict each other; the Bible must be read in the light of reason, and of God we can say only what He is not.","obras":["Guide for the Perplexed","Mishneh Torah"],"block":"med","subjects":["fil"],"temas":["fil-grandes-preguntas"]},"roger_bacon":{"name":"Roger Bacon","dates":"c. 1220 – c. 1292","born":1220,"died":1292,"place":"Ilchester (England)","role":"Franciscan philosopher and scientist","idea":"Without experience nothing can be known with certainty: science needs to test its claims and rely on mathematics.","obras":["Opus Maius","Opus Minus","Opus Tertium"],"block":"med","subjects":["fil"],"temas":["fil-t3"]},"tomas":{"name":"Thomas Aquinas","dates":"1225 – 1274","born":1225,"died":1274,"place":"Roccasecca (Italy)","role":"Scholastic philosopher and theologian","idea":"Faith and reason do not contradict each other but cooperate: reason demonstrates the existence of God from experience and prepares the way for faith.","obras":["Summa Theologiae (1265–1274)","Summa contra Gentiles","On Being and Essence"],"fuente":"William of Tocco, History of Saint Thomas Aquinas","tradicion":true,"vida":[{"a":1259,"b":1265,"t":"Writes the Summa contra Gentiles"},{"a":1265,"b":1274,"t":"Writes the Summa Theologiae"}],"block":"med","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-metafisica","fil-t7","fil-grandes-preguntas","fil-montaigne-ensayos"]},"ockham":{"name":"William of Ockham","dates":"c. 1287 – 1347","born":1287,"died":1347,"place":"Ockham (Surrey, England)","role":"Franciscan philosopher and theologian","idea":"Only individuals exist and entities must not be multiplied without necessity; reason cannot demonstrate the truths of the faith.","obras":["Summa Logicae (c. 1323)","Commentary on the Sentences","Quodlibets","Dialogue"],"fuente":"Phrase attributed by later tradition; not found in his writings","tradicion":true,"vida":[{"a":1324,"t":"Summoned to Avignon on suspicion of heresy"},{"a":1328,"t":"Flees to Munich, to the emperor Louis of Bavaria"}],"block":"med","subjects":["fil"],"temas":["fil-t3","fil-t4","fil-t5","fil-grandes-preguntas"]},"pizan":{"name":"Christine de Pizan","dates":"1364 – c. 1430","born":1364,"died":1430,"place":"Venice; lived at the French court","role":"writer and thinker","idea":"The first woman in Europe to live by her pen; in *The Book of the City of Ladies* she refuted the misogyny of her age with arguments and defended the dignity and the intellectual capacity of women.","obras":["The Book of the City of Ladies","The Book of the Three Virtues","The Letter to the God of Love","Song in honour of Joan of Arc (Ditié de Jehanne d'Arc)"],"fuente":"Christine de Pizan, *The Book of the City of Ladies*; Simone de Beauvoir, *The Second Sex* (introduction); adapted from Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, ‘En diálogo con…’ series; CC BY-NC-SA 4.0)","tradicion":true,"block":"med","subjects":["fil"],"temas":["fil-t1-filosofia-mujer"]},"erasmo":{"name":"Erasmus of Rotterdam","dates":"c. 1466 – 1536","born":1466,"died":1536,"place":"Rotterdam (Netherlands)","role":"humanist and theologian","idea":"True religion is living with goodness and in peace following the Gospel, not ceremonies or the disputes of theologians; and for this we need to read texts well and to educate.","obras":["The Praise of Folly","Handbook of the Christian Soldier","On Free Will","The Complaint of Peace"],"fuente":"Erasmus, letter to Johannes Caesarius (1524)","tradicion":true,"block":"ren","subjects":["fil"],"temas":["fil-grandes-preguntas"]},"tomas_moro":{"name":"Thomas More","dates":"1478 – 1535","born":1478,"died":1535,"place":"London (England)","role":"humanist, jurist and politician","idea":"A just society requires abolishing private property and organising everyone’s work so that no one is in need.","obras":["Utopia"],"fuente":"William Roper, The Life of Sir Thomas More; Edward Hall, Chronicle","tradicion":true,"block":"ren","subjects":["fil"],"temas":["fil-t6"]},"lutero":{"name":"Martin Luther","dates":"1483 – 1546","born":1483,"died":1546,"place":"Eisleben (Saxony, Germany)","role":"theologian and religious reformer","idea":"The human being is saved by faith alone, and every believer can read and interpret the Bible directly without depending on the authority of the Church.","obras":["The 95 Theses (1517)","The Freedom of a Christian (1520)","To the Christian Nobility of the German Nation (1520)","The Bondage of the Will (1525)"],"fuente":"Luther’s own testimony (Table Talk)","tradicion":false,"block":"ren","subjects":["fil"],"temas":["fil-grandes-preguntas"]},"calvino":{"name":"John Calvin","dates":"1509 – 1564","born":1509,"died":1564,"place":"Noyon (Picardy, France)","role":"Protestant theologian and reformer","idea":"God, the absolute sovereign, has predestined from eternity who will be saved, and the believer must live with discipline and responsibility according to His word.","obras":["Institutes of the Christian Religion (1536)"],"fuente":"Calvin, preface to the Commentary on the Psalms","tradicion":false,"block":"ren","subjects":["fil"],"temas":["fil-comunidades-perseguidos"]},"servet":{"name":"Michael Servetus","dates":"1511 – 1553","born":1511,"died":1553,"place":"Villanueva de Sijena (Aragon)","role":"Aragonese physician and theologian","idea":"He argued that there is no basis for the dogma of the Trinity and called for freedom to think in matters of religion; he also described how the blood passes through the lungs.","obras":["On the Errors of the Trinity (De Trinitatis erroribus, 1531)","The Restoration of Christianity (Christianismi restitutio, 1553)"],"fuente":"Michael Servetus, Christianismi restitutio (1553), where the pulmonary circulation is described; from the few copies that escaped the burning","tradicion":false,"block":"ren","subjects":["fil"],"temas":["fil-comunidades-perseguidos"]},"montaigne":{"name":"Michel de Montaigne","dates":"1533 – 1592","born":1533,"died":1592,"place":"Château de Montaigne (Périgord, France)","role":"French humanist and essayist","idea":"The best subject of study is oneself: by honestly examining your own life, changeable and contradictory, you learn what it is to be human and how little we know for certain.","obras":["Essays (1580; expanded in 1588; posthumous edition of 1595)","Travel Journal to Italy (written in 1580-1581, published in 1774)"],"fuente":"Inscriptions in Montaigne’s tower (1571)","tradicion":false,"block":"ren","subjects":["fil"],"temas":["fil-montaigne-ensayos"]},"giordano_bruno":{"name":"Giordano Bruno","dates":"1548 – 1600","born":1548,"died":1600,"place":"Nola (near Naples, Italy)","role":"philosopher and cosmologist","idea":"The universe is infinite and full of infinite worlds; every star is a sun with its own planets.","obras":["On the Infinite Universe and Worlds","The Ash Wednesday Supper","On Cause, Principle and Unity"],"block":"ren","subjects":["fil"],"temas":["fil-comunidades-perseguidos"]},"francis_bacon":{"name":"Francis Bacon","dates":"1561 – 1626","born":1561,"died":1626,"place":"London (England)","role":"philosopher, jurist and politician","idea":"Knowledge is power: science must start from the observation of nature and advance by induction, free from the prejudices of the mind.","obras":["Novum Organum","Essays","The New Atlantis"],"fuente":"John Aubrey, Brief Lives","tradicion":true,"block":"ren","subjects":["fil"],"temas":["fil-t3"]},"galileo":{"name":"Galileo Galilei","dates":"1564 – 1642","born":1564,"died":1642,"place":"Pisa (Italy)","role":"physicist and astronomer","idea":"Nature is written in the language of mathematics, and only controlled experiment and measurement allow us to know its laws, not the authority of Aristotle.","obras":["The Starry Messenger (1610)","Dialogue Concerning the Two Chief World Systems (1632)","Discourses and Mathematical Demonstrations Relating to Two New Sciences (1638)"],"fuente":"Vincenzo Viviani, Historical Account of the Life of Galileo","tradicion":true,"block":"ren","subjects":["fil"],"temas":["fil-t3","fil-comunidades-perseguidos"]},"kepler":{"name":"Johannes Kepler","dates":"1571 – 1630","born":1571,"died":1630,"place":"Weil der Stadt (Germany)","role":"astronomer and mathematician","idea":"The planets do not move in perfect circles, but in elliptical orbits with the Sun at one of the foci, following precise mathematical laws.","obras":["The Cosmographic Mystery (1596)","New Astronomy (1609)","The Harmony of the World (1619)"],"fuente":"Kepler, The Cosmographic Mystery (Mysterium cosmographicum), preface","tradicion":false,"block":"ren","subjects":["fil"],"temas":["fil-t3"]},"harvey":{"name":"William Harvey","dates":"1578 – 1657","born":1578,"died":1657,"place":"Folkestone (England)","role":"physician and physiologist","idea":"Blood circulates continuously through the body, driven by the heart, which acts as a pump, and observation and experiment demonstrate this.","obras":["On the Motion of the Heart and Blood in Animals (1628)"],"fuente":"John Aubrey, Brief Lives","tradicion":true,"block":"ren","subjects":["fil"],"temas":["fil-marxismos"]},"hobbes":{"name":"Thomas Hobbes","dates":"1588 – 1679","born":1588,"died":1679,"place":"Westport, Malmesbury (England)","role":"philosopher and political theorist","idea":"Without a State, human beings live in a war of all against all; out of fear of death, they agree to hand all their power over to an absolute sovereign.","obras":["The Elements of Law, Natural and Politic (1640)","On the Citizen (1642)","Leviathan (1651)","On the Body (1655)"],"fuente":"John Aubrey, Brief Lives","tradicion":false,"block":"mod","subjects":["fil"],"temas":["fil-t2","fil-metafisica","fil-t6","fil-grandes-preguntas"]},"descartes":{"name":"René Descartes","dates":"1596 – 1650","born":1596,"died":1650,"place":"La Haye (Touraine, France)","role":"philosopher and mathematician","idea":"By doubting everything methodically, one reaches an indubitable truth, I think, therefore I am, from which reason reconstructs all knowledge with certainty.","obras":["Rules for the Direction of the Mind (c. 1628; published in 1701)","The World (1633; he gave up publishing it after Galileo’s condemnation)","Discourse on Method, with the Optics, the Meteorology and the Geometry (1637)","Meditations on First Philosophy (1641)","Principles of Philosophy (1644)","The Passions of the Soul (1649)"],"fuente":"Descartes, Discourse on Method II; Adrien Baillet, Life of Descartes","tradicion":false,"vida":[{"a":1604,"b":1612,"t":"Studies at the Jesuit college of La Flèche"},{"a":1616,"t":"Graduates in Law at Poitiers"},{"a":1618,"t":"Volunteer soldier in the Netherlands; meets Beeckman"},{"a":1619,"t":"The three dreams of 10 November"},{"a":1628,"b":1649,"t":"Lives in the Netherlands"},{"a":1633,"t":"Gives up publishing The World after Galileo’s condemnation"},{"a":1637,"t":"Discourse on Method"},{"a":1641,"t":"Meditations on First Philosophy"},{"a":1644,"t":"Principles of Philosophy"},{"a":1649,"t":"The Passions of the Soul; travels to Sweden at the invitation of Queen Christina"}],"block":"ren","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t3","fil-metafisica","fil-spinoza-sistema","fil-grandes-preguntas","fil-montaigne-ensayos"]},"isabel":{"name":"Elisabeth of Bohemia","dates":"1618 – 1680","born":1618,"died":1680,"place":"Heidelberg (Germany)","role":"princess and philosopher","idea":"If the soul is immaterial and the body is pure extension, it is not understood how the soul can move the body: Cartesian dualism needs an explanation.","obras":["Correspondence with Descartes (1643–1649)"],"fuente":"Descartes, dedication of the Principles of Philosophy (1644)","tradicion":false,"block":"mod","subjects":["fil"],"temas":["fil-metafisica","fil-grandes-preguntas"]},"pascal":{"name":"Blaise Pascal","dates":"1623 – 1662","born":1623,"died":1662,"place":"Clermont (Auvergne, France)","role":"mathematician, physicist and philosopher","idea":"Reason is powerful but limited: the human being is a thinking reed, both fragile and great, and ‘the heart has its reasons which reason does not know’.","obras":["New Experiments Concerning the Vacuum (1647)","Provincial Letters (1656-1657)","Pensées (posthumous, 1670)"],"fuente":"Pascal’s Memorial (1654), kept at the National Library of France","tradicion":false,"block":"mod","subjects":["fil"],"temas":["fil-metafisica","fil-montaigne-ensayos"]},"spinoza":{"name":"Baruch Spinoza","dates":"1632 – 1677","born":1632,"died":1677,"place":"Amsterdam (Netherlands)","role":"rationalist philosopher","idea":"There is only one substance, God or Nature, and thought and extension are two of its attributes; freedom consists in understanding necessity.","obras":["Theological-Political Treatise (1670)","Ethics Demonstrated in Geometrical Order (1677)","Treatise on the Emendation of the Intellect (1677)"],"fuente":"Leibniz, notes of his conversation with Spinoza (1676)","tradicion":false,"vida":[{"a":1677,"t":"The Ethics is published, posthumously"}],"block":"mod","subjects":["fil"],"temas":["fil-t3","fil-metafisica","fil-spinoza-sistema","fil-grandes-preguntas","fil-comunidades-perseguidos","fil-montaigne-ensayos"]},"locke":{"name":"John Locke","dates":"1632 – 1704","born":1632,"died":1704,"place":"Wrington (England)","role":"empiricist philosopher and politician","idea":"The mind is born as a blank sheet that experience fills, and political power is legitimate only if it protects the natural rights of life, liberty and property.","obras":["A Letter Concerning Toleration (1689)","An Essay Concerning Human Understanding (1690)","Two Treatises of Government (1690)"],"fuente":"Locke, ‘Epistle to the Reader’ of the Essay Concerning Human Understanding","tradicion":false,"block":"mod","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t3","fil-t6","fil-grandes-preguntas"]},"malebranche":{"name":"Nicolas Malebranche","dates":"1638 – 1715","born":1638,"died":1715,"place":"Paris (France)","role":"rationalist philosopher and priest","idea":"Creatures cause nothing by themselves: God is the only true cause and acts on each occasion to coordinate soul and body.","obras":["The Search after Truth (1674–1675)","Treatise on Nature and Grace (1680)","Dialogues on Metaphysics and on Religion (1688)"],"block":"mod","subjects":["fil"],"temas":["fil-t3"]},"newton":{"name":"Isaac Newton","dates":"1642 – 1727","born":1642,"died":1727,"place":"Woolsthorpe (England)","role":"physicist and mathematician","idea":"One and the same law of universal gravitation explains both the fall of bodies on Earth and the motion of the planets, unifying terrestrial and celestial physics.","obras":["Mathematical Principles of Natural Philosophy (1687)","Opticks (1704)"],"fuente":"William Stukeley, Memoirs of Sir Isaac Newton’s Life","tradicion":true,"block":"mod","subjects":["fil"],"temas":["fil-t1","fil-t3","fil-metafisica","fil-marxismos"]},"leibniz":{"name":"Gottfried Wilhelm Leibniz","dates":"1646 – 1716","born":1646,"died":1716,"place":"Leipzig (Germany)","role":"rationalist philosopher and mathematician","idea":"Reality is made up of infinite monads, simple substances that do not interact, whose order God synchronised from the beginning in the best of all possible worlds.","obras":["Discourse on Metaphysics (1686)","New Essays on Human Understanding (written in 1704)","Theodicy (1710)","Monadology (1714)"],"fuente":"Leibniz’s autobiographical notes","tradicion":false,"block":"mod","subjects":["fil"],"temas":["fil-t3","fil-metafisica","fil-t4"]},"berkeley":{"name":"George Berkeley","dates":"1685 – 1753","born":1685,"died":1753,"place":"County Kilkenny (Ireland)","role":"empiricist philosopher and bishop","idea":"To be is to be perceived: material things do not exist outside the mind, but are collections of perceived ideas, ultimately sustained by God.","obras":["An Essay Towards a New Theory of Vision (1709)","A Treatise Concerning the Principles of Human Knowledge (1710)","Three Dialogues between Hylas and Philonous (1713)"],"fuente":"James Boswell, Life of Samuel Johnson","tradicion":false,"block":"mod","subjects":["fil"],"temas":["fil-t3","fil-metafisica","fil-grandes-preguntas"]},"montesquieu":{"name":"Montesquieu","dates":"1689 – 1755","born":1689,"died":1755,"place":"La Brède, near Bordeaux (France)","role":"Enlightenment political thinker","idea":"To avoid despotism and guarantee freedom, power must be divided into legislative, executive and judicial, so that each power checks the others.","obras":["Persian Letters (1721)","The Spirit of the Laws (1748)"],"block":"ilu","subjects":["fil"],"temas":["fil-t6"]},"voltaire":{"name":"Voltaire","dates":"1694 – 1778","born":1694,"died":1778,"place":"Paris (France)","role":"writer and Enlightenment philosopher","idea":"Reason must combat fanaticism and superstition; religious tolerance and freedom of expression are conditions of a civilised society.","obras":["Philosophical Letters (1734)","Candide (1759)","Treatise on Tolerance (1763)","Philosophical Dictionary (1764)"],"fuente":"Biographies of Voltaire, based on testimonies of the period","tradicion":false,"block":"ilu","subjects":["fil"],"temas":[]},"euler":{"name":"Leonhard Euler","dates":"1707 – 1783","born":1707,"died":1783,"place":"Basel (Switzerland)","role":"Swiss mathematician","idea":"Relations between classes can be seen as relations between circles: one inside another, separate or overlapping.","obras":["Introduction to the Analysis of the Infinite (1748)","Letters to a German Princess (1768-1772)"],"fuente":"J. J. O'Connor and E. F. Robertson, ‘Leonhard Euler’, MacTutor History of Mathematics","block":"ilu","subjects":["fil"],"temas":["fil-t4"]},"lamettrie":{"name":"Julien Offray de La Mettrie","dates":"1709 – 1751","born":1709,"died":1751,"place":"Saint-Malo (France)","role":"physician and materialist philosopher","idea":"The human being is a complex machine: the soul is not a spiritual substance, but the result of the functioning of the organs, above all the brain.","obras":["Natural History of the Soul (1745)","Man a Machine (1748)"],"fuente":"Letters from Voltaire in Berlin; Frederick II, Eulogy of La Mettrie","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t2"]},"hume":{"name":"David Hume","dates":"1711 – 1776","born":1711,"died":1776,"place":"Edinburgh (Scotland)","role":"empiricist philosopher and historian","idea":"All knowledge comes from the impressions of experience; ideas such as causality or the substantial self are justified not by reason, but by custom.","obras":["A Treatise of Human Nature (1739-1740)","An Enquiry Concerning Human Understanding (1748)","An Enquiry Concerning the Principles of Morals (1751)","Dialogues Concerning Natural Religion (1779)"],"fuente":"Edinburgh tradition, recorded in biographies of Hume (E. C. Mossner, The Life of David Hume)","tradicion":true,"vida":[{"a":1739,"b":1740,"t":"A Treatise of Human Nature"}],"block":"ilu","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t3","fil-metafisica","fil-t4","fil-t5","fil-t6","fil-t7","fil-grandes-preguntas","fil-montaigne-ensayos"]},"rousseau":{"name":"Jean-Jacques Rousseau","dates":"1712 – 1778","born":1712,"died":1778,"place":"Geneva (Switzerland)","role":"philosopher and political theorist","idea":"Human beings are good by nature and society corrupts them; a legitimate social contract requires obedience to the general will, the expression of popular sovereignty.","obras":["Discourse on the Origin of Inequality (1755)","The Social Contract (1762)","Emile, or On Education (1762)"],"fuente":"Rousseau, Confessions, Book VIII; Second Letter to Malesherbes (1762)","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t6","fil-grandes-preguntas","fil-montaigne-ensayos"]},"baumgarten":{"name":"Alexander Baumgarten","dates":"1714 – 1762","born":1714,"died":1762,"place":"Berlin (Germany)","role":"German rationalist philosopher","idea":"Sensory knowledge has its own perfection, beauty, and deserves a specific philosophical discipline, which he called aesthetics.","obras":["Philosophical Meditations on Some Matters Pertaining to the Poem (1735)","Metaphysics (1739)","Aesthetics (1750-1758)"],"block":"ilu","subjects":["fil"],"temas":["fil-t7"]},"holbach":{"name":"Baron d’Holbach","dates":"1723 – 1789","born":1723,"died":1789,"place":"Edesheim (Palatinate, Germany)","role":"materialist philosopher and encyclopédiste","idea":"Only matter in motion exists; the human being is part of nature, and religion is born of fear and ignorance.","obras":["System of Nature","Christianity Unveiled"],"block":"ilu","subjects":["fil"],"temas":["fil-metafisica","fil-grandes-preguntas"]},"kant":{"name":"Immanuel Kant","dates":"1724 – 1804","born":1724,"died":1804,"place":"Königsberg (Prussia)","role":"German Enlightenment philosopher","idea":"We know only the phenomena ordered by the subject’s a priori forms; and morality is founded on the duty that autonomous reason gives itself.","obras":["Critique of Pure Reason (1781)","Groundwork of the Metaphysics of Morals (1785)","Critique of Practical Reason (1788)","Critique of Judgement (1790)"],"fuente":"Biographical tradition; on his habits, biographies by Borowski, Jachmann and Wasianski","tradicion":true,"block":"ilu","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t3","fil-metafisica","fil-t5","fil-t6","fil-t7","fil-grandes-preguntas","fil-montaigne-ensayos"]},"paley":{"name":"William Paley","dates":"1743 – 1805","born":1743,"died":1805,"place":"Peterborough (England)","role":"English clergyman and philosopher","idea":"If, on finding a watch, we infer that someone made it, then the eye and the other organs of living beings, which are far more complex, require an intelligent designer.","obras":["The Principles of Moral and Political Philosophy (1785)","A View of the Evidences of Christianity (1794)","Natural Theology (1802)"],"fuente":"Letter from Charles Darwin to John Lubbock, 22 November 1859 (Darwin Correspondence Project)","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-metafisica","fil-t4"]},"condorcet":{"name":"Nicolas de Condorcet","dates":"1743 – 1794","born":1743,"died":1794,"place":"Ribemont (Picardy, France)","role":"mathematician, Enlightenment philosopher and politician of the French Revolution","idea":"Humanity can progress without any limit fixed in advance thanks to reason, science and education, and that progress demands the same rights for everyone: for women and for slaves too.","obras":["Reflections on Negro Slavery (1781)","Essay on the Application of Analysis to the Probability of Majority Decisions (1785)","On the Admission of Women to the Rights of Citizenship (1790)","Five Memoirs on Public Education (1791)","Sketch for a Historical Picture of the Progress of the Human Mind (1795, posthumous)"],"fuente":"Traditional story repeated by his biographers since the 19th century; the details of the arrest are not reliably documented","tradicion":true,"block":"ilu","subjects":["fil"],"temas":["fil-comunidades-perseguidos"]},"lamarck":{"name":"Jean-Baptiste Lamarck","dates":"1744 – 1829","born":1744,"died":1829,"place":"Bazentin (Picardy, France)","role":"French naturalist","idea":"Species are not fixed but are transformed over time: some descend from others through changes that gradually accumulate.","obras":["Flore françoise (1778)","Zoological Philosophy (1809)"],"fuente":"François Arago, Histoire de ma jeunesse","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2"]},"bentham":{"name":"Jeremy Bentham","dates":"1748 – 1832","born":1748,"died":1832,"place":"London","role":"utilitarian philosopher and jurist","idea":"An action is good if it increases the pleasure and reduces the pain of those affected; morality and laws should seek the greatest happiness for the greatest number.","obras":["A Fragment on Government (1776)","An Introduction to the Principles of Morals and Legislation (1789)","Panopticon (1791)"],"fuente":"Bentham’s will; University College London","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t5","fil-t6","fil-grandes-preguntas"]},"gouges":{"name":"Olympe de Gouges","dates":"1748 – 1793","born":1748,"died":1793,"place":"Montauban (France)","role":"writer and political activist","idea":"The rights proclaimed by the French Revolution must also apply to women, who are citizens with the same rights as men.","obras":["Declaration of the Rights of Woman and of the Female Citizen (1791)"],"fuente":"Letter from Olympe de Gouges to the Convention (December 1792)","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t6","fil-t1-filosofia-mujer","fil-grandes-preguntas"]},"wollstonecraft":{"name":"Mary Wollstonecraft","dates":"1759 – 1797","born":1759,"died":1797,"place":"London","role":"philosopher and writer","idea":"The supposed intellectual inferiority of women is not natural, but the result of their education; with the same training, they would develop the same reason as men.","obras":["Thoughts on the Education of Daughters (1787)","A Vindication of the Rights of Men (1790)","A Vindication of the Rights of Woman (1792)"],"fuente":"Wollstonecraft, Letters Written in Sweden, Norway, and Denmark; William Godwin, Memoirs of the Author of A Vindication of the Rights of Woman","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t6","fil-t1-filosofia-mujer","fil-grandes-preguntas"]},"schiller":{"name":"Friedrich Schiller","dates":"1759 – 1805","born":1759,"died":1805,"place":"Marbach am Neckar (Germany)","role":"playwright, poet and historian","idea":"Human beings are only fully free when reason and sensibility stop fighting, and beauty is the path for educating them in that harmony.","obras":["The Robbers (1781)","On Grace and Dignity (1793)","Letters on the Aesthetic Education of Man (1795)","William Tell (1804)"],"fuente":"Decree of the French Legislative Assembly (26 August 1792); the diploma reached Weimar in March 1798","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t7"]},"hegel":{"name":"Georg Wilhelm Friedrich Hegel","dates":"1770 – 1831","born":1770,"died":1831,"place":"Stuttgart (Germany)","role":"German idealist philosopher","idea":"Reality is a dialectical process in which Spirit develops through history; each philosophy is its own age expressed in thought.","obras":["Phenomenology of Spirit (1807)","Science of Logic (1812-1816)","Encyclopaedia of the Philosophical Sciences (1817)","Elements of the Philosophy of Right (1821)"],"fuente":"Letter from Hegel to Niethammer, 13 October 1806","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t3","fil-t6","fil-t7","fil-grandes-preguntas","fil-montaigne-ensayos"]},"thompson":{"name":"William Thompson","dates":"1775 – 1833","born":1775,"died":1833,"place":"Cork (Ireland)","role":"Irish economist and socialist thinker","idea":"Whoever works has a right to everything they produce; the wealth that owners keep without working is an injustice.","obras":["An Inquiry into the Principles of the Distribution of Wealth (1824)","Appeal of One Half the Human Race, Women, Against the Pretensions of the Other Half, Men (1825)","Labour Rewarded (1827)"],"fuente":"Thompson’s will and the subsequent lawsuit; local press in Cork","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-marxismos"]},"feuerbach":{"name":"Ludwig Feuerbach","dates":"1804 – 1872","born":1804,"died":1872,"place":"Landshut (Bavaria)","role":"German materialist philosopher","idea":"God is nothing more than the projection of idealised human qualities; by worshipping Him, the human being becomes alienated and separated from his own essence.","obras":["The Essence of Christianity (1841)","Provisional Theses for the Reform of Philosophy (1842)","Principles of the Philosophy of the Future (1843)"],"fuente":"Feuerbach, review of Moleschott’s work on nutrition (1850)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6"]},"mill":{"name":"John Stuart Mill","dates":"1806 – 1873","born":1806,"died":1873,"place":"London","role":"British philosopher and economist","idea":"The right action is the one that promotes the greatest happiness of the greatest number, but intellectual and moral pleasures are worth more than purely physical ones.","obras":["A System of Logic (1843)","On Liberty (1859)","Utilitarianism (1863)","The Subjection of Women (1869)"],"fuente":"John Stuart Mill, Autobiography","tradicion":false,"block":"ilu","subjects":["fil"],"temas":["fil-t5","fil-t6","fil-comunidades-perseguidos"]},"de_morgan":{"name":"Augustus De Morgan","dates":"1806 – 1871","born":1806,"died":1871,"place":"Madurai (India)","role":"British mathematician and logician","idea":"Denying ‘A or B’ is asserting ‘neither A nor B’, and denying ‘A and B’ is asserting ‘not A, or not B’: the laws that bear his name.","obras":["Formal Logic (1847)","A Budget of Paradoxes (1872, posthumous)"],"fuente":"J. J. O'Connor and E. F. Robertson, ‘Augustus De Morgan’, MacTutor History of Mathematics","block":"con","subjects":["fil"],"temas":["fil-t4"]},"darwin":{"name":"Charles Darwin","dates":"1809 – 1882","born":1809,"died":1882,"place":"Shrewsbury (England)","role":"British naturalist","idea":"All species descend from common ancestors and are slowly transformed by natural selection, which favours the individuals best adapted to their environment.","obras":["The Voyage of the Beagle (1839)","On the Origin of Species (1859)","The Descent of Man (1871)"],"fuente":"Charles Darwin, Autobiography","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2","fil-metafisica","fil-t4"]},"kierkegaard":{"name":"Søren Kierkegaard","dates":"1813 – 1855","born":1813,"died":1855,"place":"Copenhagen (Denmark)","role":"Danish philosopher and theologian, forerunner of existentialism","idea":"The truth that matters is not that of systems, but the one you live: each individual has to choose themselves, and that choice is made in anxiety.","obras":["Either/Or (1843)","Fear and Trembling (1843)","The Concept of Anxiety (1844)","The Sickness unto Death (1849)"],"fuente":"The Corsair (1846); Kierkegaard’s journals","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-metafisica"]},"boole":{"name":"George Boole","dates":"1815 – 1864","born":1815,"died":1864,"place":"Lincoln (England)","role":"British mathematician and logician","idea":"Logic can be treated as an algebra: with 1 for true and 0 for false, the connectives become operations of calculation.","obras":["The Mathematical Analysis of Logic (1847)","The Laws of Thought (1854)"],"fuente":"Desmond MacHale, George Boole: His Life and Work","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t4"]},"marx":{"name":"Karl Marx","dates":"1818 – 1883","born":1818,"died":1883,"place":"Trier (Prussia)","role":"philosopher, economist and revolutionary","idea":"The economic structure determines society and its ideas; under capitalism the worker is alienated and exploited, and only a revolution can create a classless society.","obras":["Economic and Philosophic Manuscripts (1844)","Theses on Feuerbach (1845)","The Communist Manifesto (1848)","Capital (1867)"],"fuente":"Letter from Engels to Eduard Bernstein (1882)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t5","fil-t6","fil-grandes-preguntas","fil-marxismos"]},"mendel":{"name":"Gregor Mendel","dates":"1822 – 1884","born":1822,"died":1884,"place":"Heinzendorf (Silesia, now the Czech Republic)","role":"Augustinian friar and naturalist","idea":"Hereditary traits are transmitted through separate units, today called genes, which combine from generation to generation according to regular, predictable proportions.","obras":["Experiments on Plant Hybridisation (1866)"],"fuente":"Mendel’s correspondence with Carl von Nägeli","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2","fil-marxismos"]},"wallace":{"name":"Alfred Russel Wallace","dates":"1823 – 1913","born":1823,"died":1913,"place":"Usk (Wales)","role":"British naturalist and explorer","idea":"Species change through natural selection: the individuals best adapted survive and reproduce more, an idea he formulated independently of Darwin.","obras":["On the Tendency of Varieties to Depart Indefinitely from the Original Type (1858)","The Malay Archipelago (1869)","Darwinism (1889)"],"fuente":"Alfred Russel Wallace, My Life (autobiography)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2"]},"tylor":{"name":"Edward B. Tylor","dates":"1832 – 1917","born":1832,"died":1917,"place":"London","role":"British anthropologist","idea":"Culture is the set of knowledge, beliefs, art, morals, law and customs that a person acquires as a member of a society.","obras":["Primitive Culture (1871)","Anthropology (1881)"],"fuente":"Edward B. Tylor, Anahuac (1861)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2"]},"venn":{"name":"John Venn","dates":"1834 – 1923","born":1834,"died":1923,"place":"Hull (England)","role":"British logician and philosopher","idea":"To check a piece of reasoning, you have to draw all the possible regions and mark which ones are empty.","obras":["The Logic of Chance (1866)","Symbolic Logic (1881)","The Principles of Empirical or Inductive Logic (1889)"],"fuente":"J. J. O'Connor and E. F. Robertson, ‘John Venn’, MacTutor History of Mathematics","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t4"]},"james":{"name":"William James","dates":"1842 – 1910","born":1842,"died":1910,"place":"New York","role":"American philosopher and psychologist","idea":"An idea is true if it works in practice: truth is measured by its consequences and by its usefulness in guiding our experience.","obras":["The Principles of Psychology (1890)","The Will to Believe (1897)","The Varieties of Religious Experience (1902)","Pragmatism (1907)"],"fuente":"William James, Pragmatism (1907), Lecture II","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t3"]},"nietzsche":{"name":"Friedrich Nietzsche","dates":"1844 – 1900","born":1844,"died":1900,"place":"Röcken (Saxony, Prussia)","role":"German philosopher and philologist","idea":"After the death of God and the collapse of traditional values, human beings must overcome nihilism by affirming life and creating their own values.","obras":["The Birth of Tragedy (1872)","The Gay Science (1882)","Thus Spoke Zarathustra (1883-1885)","On the Genealogy of Morality (1887)"],"fuente":"Letter from Nietzsche to Heinrich Köselitz (February 1882)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t5","fil-grandes-preguntas","fil-montaigne-ensayos"]},"frege":{"name":"Gottlob Frege","dates":"1848 – 1925","born":1848,"died":1925,"place":"Wismar (Mecklenburg)","role":"mathematician, logician and philosopher","idea":"With a formal language of symbols, logic can eliminate the ambiguities of ordinary language and serve as the foundation of all arithmetic.","obras":["Begriffsschrift (Concept Notation) (1879)","The Foundations of Arithmetic (1884)","On Sense and Reference (1892)","Basic Laws of Arithmetic (1893-1903)"],"fuente":"Wittgenstein’s testimony recorded by Peter Geach; preface to the Tractatus Logico-Philosophicus","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t4"]},"freud":{"name":"Sigmund Freud","dates":"1856 – 1939","born":1856,"died":1939,"place":"Freiberg (Moravia, now Czech Republic)","role":"neurologist, creator of psychoanalysis","idea":"Most of psychic life is unconscious: repressed desires that we do not control govern what we think and do, and their repression produces neuroses.","obras":["The Interpretation of Dreams (1900)","Three Essays on the Theory of Sexuality (1905)","The Ego and the Id (1923)","Civilization and Its Discontents (1930)"],"fuente":"Ernest Jones, The Life and Work of Sigmund Freud","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2","fil-t5"]},"whitehead":{"name":"Alfred North Whitehead","dates":"1861 – 1947","born":1861,"died":1947,"place":"Ramsgate (England)","role":"British mathematician and philosopher","idea":"Together with Russell he tried to show that arithmetic can be derived from logic, and later he conceived reality as a process of events in becoming.","obras":["Principia Mathematica (1910-1913, with Russell)","Process and Reality (1929)"],"fuente":"Bertrand Russell, Autobiography","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t4"]},"unamuno":{"name":"Miguel de Unamuno","dates":"1864 – 1936","born":1864,"died":1936,"place":"Bilbao","role":"philosopher, novelist and poet","idea":"The human being of flesh and blood lives in agony, in permanent struggle between reason, which denies immortality, and the heart, which longs for it.","obras":["The Tragic Sense of Life (1913)","Mist (1914)","The Agony of Christianity (1925)","Saint Manuel Bueno, Martyr (1931)"],"fuente":"Unamuno, Love and Pedagogy (1902), ‘Notes for a Treatise on Cocotology’","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6"]},"weber":{"name":"Max Weber","dates":"1864 – 1920","born":1864,"died":1920,"place":"Erfurt (Germany)","role":"German sociologist, economist and philosopher","idea":"The modern State rests on a legal and rational legitimacy, and political action must combine the ethic of conviction with the ethic of responsibility.","obras":["The Protestant Ethic and the Spirit of Capitalism (1905)","Science as a Vocation (1919)","Politics as a Vocation (1919)","Economy and Society (1922)"],"fuente":"Weber, Politics as a Vocation (lecture of 1919); Marianne Weber, biography of Max Weber","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6","fil-marxismos"]},"curie":{"name":"Marie Curie","dates":"1867 – 1934","born":1867,"died":1934,"place":"Warsaw (Poland)","role":"physics and chemistry","idea":"She studied radioactivity as a property of atoms and discovered two new elements, polonium and radium, opening the way to nuclear physics.","obras":["Discovery of polonium and radium (1898, with Pierre Curie)","Treatise on Radioactivity (1910)"],"fuente":"Marie Curie, Pierre Curie (1923), autobiographical notes","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t3"]},"luxemburgo":{"name":"Rosa Luxemburg","dates":"1871 – 1919","born":1871,"died":1919,"place":"Zamość (Poland)","role":"Marxist thinker and revolutionary","idea":"Socialism and democracy are inseparable: she criticised both the reformism that gives up on transforming society and the rule of a single party, and trusted in the spontaneous initiative of the workers.","obras":["Reform or Revolution? (1899)","The Mass Strike, the Party and the Trade Unions (1906)","The Accumulation of Capital (1913)","The Russian Revolution (written in 1918)"],"fuente":"Rosa Luxemburg, letter to Sophie Liebknecht from Breslau prison (mid-December 1917), collected in her Letters from Prison","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6","fil-marxismos"]},"russell":{"name":"Bertrand Russell","dates":"1872 – 1970","born":1872,"died":1970,"place":"Trellech (Wales)","role":"British philosopher, logician and mathematician","idea":"The logical analysis of language makes it possible to clarify philosophical problems, and mathematics can be founded on logic; he defended a logically perfect language that reflects the structure of the world.","obras":["Principia Mathematica (1910-1913, with Whitehead)","The Problems of Philosophy (1912)","A History of Western Philosophy (1945)"],"fuente":"Correspondence between Russell and Frege (1902); Frege, appendix to vol. II of Basic Laws of Arithmetic","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t3","fil-t4"]},"kollontai":{"name":"Alexandra Kollontai","dates":"1872 – 1952","born":1872,"died":1952,"place":"Saint Petersburg (Russian Empire)","role":"Soviet revolutionary and diplomat","idea":"She brought together socialism and the emancipation of women: legal equality is not enough if domestic work, the family and love relationships do not change.","obras":["The Social Basis of the Woman Question (1909)","The New Morality and the Working Class (1918)","The Workers' Opposition (1921)","Make Way for Winged Eros! (1923)"],"fuente":"Cathy Porter, Alexandra Kollontai. A Biography (Virago, 1980)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-marxismos"]},"scheler":{"name":"Max Scheler","dates":"1874 – 1928","born":1874,"died":1928,"place":"Munich (Germany)","role":"German philosopher, phenomenologist","idea":"Values are grasped through feeling and form an objective hierarchy; the human being is distinguished by spirit, capable of distancing itself from its environment and knowing itself.","obras":["Formalism in Ethics and Non-Formal Ethics of Values (1913-1916)","Man’s Place in Nature (1928)"],"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t3"]},"einstein":{"name":"Albert Einstein","dates":"1879 – 1955","born":1879,"died":1955,"place":"Ulm (Germany)","role":"theoretical physicist","idea":"With the theory of relativity he showed that space and time are not absolute, but depend on the observer and on the presence of matter and energy.","obras":["Special theory of relativity (1905)","General theory of relativity (1915)"],"fuente":"Einstein, Autobiographical Notes (1949)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t3","fil-metafisica"]},"maeztu":{"name":"María de Maeztu","dates":"1881 – 1948","born":1881,"died":1948,"place":"Vitoria-Gasteiz","role":"educator","idea":"She put educational equality for women into practice: from the Residencia de Señoritas she opened to young women access to university and to the intellectual life of the Spain of her time.","obras":[],"fuente":"Adapted from Lola Cabrera Trigo, *El pensamiento en femenino plural* (Erein, ‘En diálogo con…’ series; CC BY-NC-SA 4.0); dates according to the Auñamendi Biographical Dictionary (Eusko Ikaskuntza) and EcuRed (she died on 7-1-1948 in Mar del Plata; the book gives 1952 in error)","tradicion":true,"block":"con","subjects":["fil"],"temas":["fil-t6"]},"ortega":{"name":"José Ortega y Gasset","dates":"1883 – 1955","born":1883,"died":1955,"place":"Madrid","role":"Spanish philosopher and essayist","idea":"Each person’s life is the radical reality: the self is inseparable from its circumstance, and truth is reached by adding together the different perspectives.","obras":["Meditations on Quixote (1914)","The Modern Theme (1923)","The Revolt of the Masses (1930)"],"fuente":"Ortega y Gasset, ‘El error Berenguer’ (El Sol, 1930) and ‘Un aldabonazo’ (Crisol, 1931)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2","fil-t3","fil-t6"]},"duchamp":{"name":"Marcel Duchamp","dates":"1887 – 1968","born":1887,"died":1968,"place":"Blainville-Crevon (France)","role":"French avant-garde artist","idea":"An ordinary object can be a work of art by the artist’s choice, so that art is no longer defined by skill or beauty.","obras":["Nude Descending a Staircase, No. 2 (1912)","Bicycle Wheel (1913)","Fountain (1917)","The Large Glass (1915-1923)"],"fuente":"Statements by Duchamp in his interviews with Pierre Cabanne","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7","fil-grandes-preguntas"]},"wittgenstein":{"name":"Ludwig Wittgenstein","dates":"1889 – 1951","born":1889,"died":1951,"place":"Vienna (Austria)","role":"Austrian philosopher of language","idea":"Philosophical problems arise from misunderstandings of language; first he conceived propositions as pictures of facts and later meaning as use in language games.","obras":["Tractatus Logico-Philosophicus (1921)","Philosophical Investigations (1953)"],"fuente":"Testimonies collected in Ray Monk’s biography, Ludwig Wittgenstein: The Duty of Genius","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-montaigne-ensayos"]},"heidegger":{"name":"Martin Heidegger","dates":"1889 – 1976","born":1889,"died":1976,"place":"Messkirch (Germany)","role":"German philosopher","idea":"The human being, Dasein, is a being thrown into the world and destined for death, who lives authentically only when he accepts his finitude and his freedom.","obras":["Being and Time (1927)","What Is Metaphysics? (1929)","The Origin of the Work of Art","Letter on Humanism (1947)"],"fuente":"Heidegger, Marburg course of 1924 (Basic Concepts of Aristotelian Philosophy); testimonies of his students, such as Arendt","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7"]},"gramsci":{"name":"Antonio Gramsci","dates":"1891 – 1937","born":1891,"died":1937,"place":"Ales (Italy)","role":"Italian Marxist thinker and politician","idea":"A class does not dominate by force alone but through hegemony: the consent it obtains through culture (school, the press, religion). That is why politics is also played out on the terrain of ideas and common sense.","obras":["The Southern Question (1926)","Letters from Prison (written 1926-1937)","Prison Notebooks (written 1929-1935)"],"fuente":"Giuseppe Fiori, Life of Antonio Gramsci (1966); records of the 1928 trial","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6","fil-marxismos"]},"benjamin":{"name":"Walter Benjamin","dates":"1892 – 1940","born":1892,"died":1940,"place":"Berlin","role":"German philosopher and critic","idea":"The technical reproduction of images destroys the aura of the unique work of art, but brings it closer to the masses and gives it a new political function.","obras":["The Origin of German Tragic Drama (1928)","The Work of Art in the Age of Mechanical Reproduction (1936)","On the Concept of History (1940)","The Arcades Project"],"fuente":"Benjamin, On the Concept of History, thesis IX; testimonies of Gershom Scholem","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7","fil-marxismos"]},"horkheimer":{"name":"Max Horkheimer","dates":"1895 – 1973","born":1895,"died":1973,"place":"Stuttgart (Germany)","role":"German philosopher and sociologist","idea":"Enlightenment reason has degraded into instrumental reason, which calculates the most effective means without asking about ends, and has thus become an instrument of domination.","obras":["Traditional and Critical Theory (1937)","Dialectic of Enlightenment (1944, with Adorno)","Eclipse of Reason (1947)"],"fuente":"Lukács, 1962 preface to The Theory of the Novel","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-marxismos"]},"marcuse":{"name":"Herbert Marcuse","dates":"1898 – 1979","born":1898,"died":1979,"place":"Berlin (Germany)","role":"Frankfurt School philosopher","idea":"Advanced industrial society creates false needs and makes us feel free while integrating us into the system, so that we lose the ability to imagine another way of living.","obras":["Reason and Revolution (1941)","Eros and Civilization (1955)","One-Dimensional Man (1964)","‘Repressive Tolerance’ (1965)"],"fuente":"Press reports from 1968; interviews with Marcuse","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6","fil-marxismos"]},"gadamer":{"name":"Hans-Georg Gadamer","dates":"1900 – 2002","born":1900,"died":2002,"place":"Marburg (Germany)","role":"German philosopher","idea":"To understand is always to interpret from within a tradition and a set of prejudices; art is not a mere object of taste, but a way in which truth happens.","obras":["Truth and Method (1960)","The Relevance of the Beautiful (1977)"],"block":"con","subjects":["fil"],"temas":["fil-t7"]},"ryle":{"name":"Gilbert Ryle","dates":"1900 – 1976","born":1900,"died":1976,"place":"Brighton (England)","role":"British analytic philosopher","idea":"Cartesian dualism is a category mistake: the mind is not a ghost inside the machine of the body, but a set of capacities and dispositions to act.","obras":["The Concept of Mind (1949)","Dilemmas (1954)"],"block":"con","subjects":["fil"],"temas":["fil-grandes-preguntas"]},"gaos":{"name":"José Gaos","dates":"1900 – 1969","born":1900,"died":1969,"place":"Gijón (Asturias)","role":"philosopher and translator of the Spanish exile in Mexico","idea":"The Spanish exiles in America were not simple ‘deportees’ but ‘transplanted ones’: they had changed land, but were still on a land of their own through the shared language and culture.","obras":["On Philosophy","Professional Confessions (1958)","History of Our Idea of the World","translation of Heidegger's «Being and Time» (1951)"],"fuente":"M. Heidegger, Being and Time, trans. José Gaos, Fondo de Cultura Económica, Mexico, 1951 (translator's preface)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6"]},"popper":{"name":"Karl Popper","dates":"1902 – 1994","born":1902,"died":1994,"place":"Vienna","role":"philosopher of science","idea":"A theory is scientific if it is falsifiable, that is, if it can be refuted by experience; science, like politics, advances by correcting its mistakes.","obras":["The Logic of Scientific Discovery (1934)","The Open Society and Its Enemies (1945)","The Poverty of Historicism (1957)","Conjectures and Refutations (1963)"],"fuente":"Popper, Unended Quest (autobiography); testimonies of those present at the session","tradicion":true,"block":"con","subjects":["fil"],"temas":["fil-t3","fil-t4","fil-t6","fil-grandes-preguntas"]},"adorno":{"name":"Theodor W. Adorno","dates":"1903 – 1969","born":1903,"died":1969,"place":"Frankfurt am Main (Germany)","role":"philosopher, sociologist and musicologist","idea":"The culture industry turns culture into a commodity that lulls the masses; only autonomous, difficult art keeps its capacity to be critical of society.","obras":["Dialectic of Enlightenment (1944, with Horkheimer)","Minima Moralia (1951)","Negative Dialectics (1966)","Aesthetic Theory (1970)"],"fuente":"Thomas Mann, The Story of a Novel: The Genesis of Doctor Faustus (1949)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7","fil-marxismos","fil-montaigne-ensayos"]},"zambrano":{"name":"María Zambrano","dates":"1904 – 1991","born":1904,"died":1991,"place":"Vélez-Málaga (Málaga)","role":"Spanish philosopher and essayist","idea":"Against a cold reason that ignores feelings and dreams, she proposes a poetic reason that unites philosophy and poetry in order to understand human life in depth.","obras":["Philosophy and Poetry (1939)","Man and the Divine (1955)","Person and Democracy (1958)","Clearings of the Forest (1977)"],"fuente":"Biographical testimonies and correspondence of María Zambrano","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t6"]},"sartre":{"name":"Jean-Paul Sartre","dates":"1905 – 1980","born":1905,"died":1980,"place":"Paris","role":"French philosopher and writer","idea":"There is no prior human nature: existence precedes essence, and each person, condemned to be free, is fully responsible for what he makes of himself.","obras":["Nausea (1938)","Being and Nothingness (1943)","Existentialism Is a Humanism (1946)","Critique of Dialectical Reason (1960)"],"fuente":"Simone de Beauvoir, The Prime of Life (La force de l’âge)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-metafisica","fil-grandes-preguntas","fil-marxismos"]},"arendt":{"name":"Hannah Arendt","dates":"1906 – 1975","born":1906,"died":1975,"place":"Linden (Hanover, Germany)","role":"philosopher and political theorist","idea":"Totalitarianism destroys plurality and the public space; even extreme evil can arise from ordinary people who give up thinking for themselves.","obras":["The Origins of Totalitarianism (1951)","The Human Condition (1958)","Eichmann in Jerusalem (1963)","Truth and Politics (1967)"],"fuente":"Interview with Günter Gaus, ‘Zur Person’ (ZDF, 1964)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t3","fil-t6","fil-grandes-preguntas"]},"beauvoir":{"name":"Simone de Beauvoir","dates":"1908 – 1986","born":1908,"died":1986,"place":"Paris","role":"French philosopher and writer","idea":"Female identity is a cultural construction and not a biological destiny: woman has been defined as man’s other and must win her freedom.","obras":["The Ethics of Ambiguity (1947)","The Second Sex (1949)","The Mandarins (1954)","Old Age (1970)"],"fuente":"Simone de Beauvoir, Memoirs of a Dutiful Daughter (1958)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t2","fil-t6","fil-t1-filosofia-mujer","fil-grandes-preguntas"]},"turing":{"name":"Alan Turing","dates":"1912 – 1954","born":1912,"died":1954,"place":"London","role":"mathematician and computing pioneer","idea":"If a machine can converse in such a way that we cannot tell it from a human being, we have reason to say that it thinks: this is the idea of the Turing test.","obras":["On Computable Numbers (1936)","Computing Machinery and Intelligence (1950)"],"fuente":"Andrew Hodges, Alan Turing: The Enigma; local press of 1926","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-metafisica"]},"camus":{"name":"Albert Camus","dates":"1913 – 1960","born":1913,"died":1960,"place":"Mondovi (Algeria)","role":"French writer and philosopher","idea":"Life is absurd because the world does not answer our demand for meaning; the answer is not to flee from it, but to live it with lucidity and revolt.","obras":["The Stranger (1942)","The Myth of Sisyphus (1942)","The Plague (1947)","The Rebel (1951)"],"fuente":"Text by Camus for the bulletin of Racing Universitaire d’Alger (1950s); biographical testimonies","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2"]},"ricoeur":{"name":"Paul Ricoeur","dates":"1913 – 2005","born":1913,"died":2005,"place":"Valence (France)","role":"French philosopher, hermeneutist","idea":"Understanding human beings requires interpreting their symbols, texts and stories, because we know ourselves only through the detour of interpretation.","obras":["Freud and Philosophy: An Essay on Interpretation (1965)","The Rule of Metaphor (1975)","Time and Narrative (1983-1985)","Oneself as Another (1990)"],"fuente":"Ricoeur, Intellectual Autobiography (Réflexion faite)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t5"]},"shannon":{"name":"Claude Shannon","dates":"1916 – 2001","born":1916,"died":2001,"place":"Petoskey (Michigan, USA)","role":"American mathematician and engineer","idea":"Boole’s logic can be built with electrical circuits and information can be measured in bits: two ideas that found computer science and digital communications.","obras":["A Symbolic Analysis of Relay and Switching Circuits (1938)","A Mathematical Theory of Communication (1948)"],"fuente":"Testimonies of his colleagues at Bell Labs; J. Soni and R. Goodman, A Mind at Play (biography, 2017)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t4"]},"franklin":{"name":"Rosalind Franklin","dates":"1920 – 1958","born":1920,"died":1958,"place":"London (United Kingdom)","role":"chemist and crystallographer","idea":"Her X-ray diffraction images of DNA, such as the celebrated Photograph 51, provided decisive data for discovering its double helix structure.","obras":["Photograph 51 (1952)","Paper on the structure of DNA in Nature (1953, with R. Gosling)"],"fuente":"Letter from Rosalind Franklin to her father (c. 1940), quoted in B. Maddox, Rosalind Franklin: The Dark Lady of DNA","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t3"]},"rawls":{"name":"John Rawls","dates":"1921 – 2002","born":1921,"died":2002,"place":"Baltimore (United States)","role":"American political philosopher","idea":"A just society is the one we would choose behind a veil of ignorance: with equal basic liberties and inequalities allowed only if they benefit the worst off.","obras":["A Theory of Justice (1971)","Political Liberalism (1993)","The Law of Peoples (1999)","Justice as Fairness: A Restatement (2001)"],"fuente":"Thomas Pogge, John Rawls: His Life and Theory of Justice; J. Rawls, ‘Fifty Years after Hiroshima’, Dissent (1995)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6","fil-grandes-preguntas"]},"kuhn":{"name":"Thomas Kuhn","dates":"1922 – 1996","born":1922,"died":1996,"place":"Cincinnati (United States)","role":"philosopher of science","idea":"Science does not advance merely by accumulating truths: it alternates long periods of normal science within a paradigm with scientific revolutions that replace it with another.","obras":["The Copernican Revolution (1957)","The Structure of Scientific Revolutions (1962)","The Essential Tension (1977)"],"fuente":"First edition of The Structure of Scientific Revolutions (International Encyclopedia of Unified Science, 1962); letters from Carnap to Kuhn studied by G. Reisch","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t3","fil-grandes-preguntas"]},"danto":{"name":"Arthur Danto","dates":"1924 – 2013","born":1924,"died":2013,"place":"Ann Arbor (Michigan, United States)","role":"philosopher and art critic","idea":"Two objects that look identical can be one art and the other not: what distinguishes them is a theory and a history of art, the artworld.","obras":["The Artworld (1964)","The Transfiguration of the Commonplace (1981)","After the End of Art (1997)","The Abuse of Beauty (2003)"],"fuente":"Danto’s intellectual autobiography in The Philosophy of Arthur C. Danto (Library of Living Philosophers, 2013)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7","fil-grandes-preguntas"]},"dickie":{"name":"George Dickie","dates":"1926 – 2020","born":1926,"died":2020,"place":"Palmetto (Florida, United States)","role":"American philosopher of art","idea":"A work of art is an object on which someone, acting on behalf of the artworld, has conferred the status of candidate for appreciation.","obras":["The Myth of the Aesthetic Attitude (1964)","Art and the Aesthetic: An Institutional Analysis (1974)","The Art Circle (1984)"],"block":"con","subjects":["fil"],"temas":["fil-t7","fil-grandes-preguntas"]},"habermas":{"name":"Jürgen Habermas","dates":"1929 – 2026","born":1929,"died":2026,"place":"Düsseldorf (Germany)","role":"German philosopher and sociologist","idea":"Reason should not be abandoned but made dialogical: norms and truths are legitimated by the consensus reached in a free, equal dialogue without coercion.","obras":["The Structural Transformation of the Public Sphere (1962)","Knowledge and Human Interests (1968)","The Theory of Communicative Action (1981)","The Philosophical Discourse of Modernity (1985)"],"fuente":"J. Habermas, ‘Mit Heidegger gegen Heidegger denken’ (Thinking with Heidegger against Heidegger), Frankfurter Allgemeine Zeitung (1953)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t1","fil-t3","fil-t5","fil-t6","fil-marxismos"]},"baudrillard":{"name":"Jean Baudrillard","dates":"1929 – 2007","born":1929,"died":2007,"place":"Reims (France)","role":"French sociologist and philosopher","idea":"We live in hyperreality: simulacra, copies without an original, no longer represent reality but replace it and seem more real than it.","obras":["The System of Objects (1968)","The Consumer Society (1970)","Simulacra and Simulation (1981)","The Gulf War Did Not Take Place (1991)"],"fuente":"Film The Matrix (1999); interview with Baudrillard in Le Nouvel Observateur (2004)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7"]},"debord":{"name":"Guy Debord","dates":"1931 – 1994","born":1931,"died":1994,"place":"Paris","role":"French thinker and filmmaker","idea":"In advanced capitalism life becomes spectacle: relationships between people pass through images that are passively contemplated and consumed.","obras":["The Society of the Spectacle (1967)","Comments on the Society of the Spectacle (1988)","Panegyric (1989)"],"fuente":"Guy Debord, Hurlements en faveur de Sade (1952); accounts of its first screenings","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t7"]},"nussbaum":{"name":"Martha Nussbaum","dates":"b. 1947","born":1947,"died":null,"place":"New York (USA)","role":"American philosopher","idea":"Justice is not measured by a country’s wealth but by the real capabilities each person has to lead a dignified life.","obras":["The Fragility of Goodness (1986)","Women and Human Development (2000)","Not for Profit (2010)","Creating Capabilities (2011)"],"fuente":"Profile by R. Aviv in The New Yorker (2016) and interviews","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-utilidad"]},"butler":{"name":"Judith Butler","dates":"b. 1956","born":1956,"died":null,"place":"Cleveland (Ohio, USA)","role":"leading figure of queer theory","idea":"Gender is not a biological essence but a performance: it is produced by repeating gestures and norms, and that is why it can be transformed and subverted.","obras":["Gender Trouble (1990)","Bodies That Matter (1993)","Precarious Life (2004)","The Force of Nonviolence (2020)"],"fuente":"Judith Butler’s testimony in interviews","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t6"]},"han":{"name":"Byung-Chul Han","dates":"b. 1959","born":1959,"died":null,"place":"Seoul (South Korea)","role":"South Korean-German philosopher","idea":"In the achievement society an external master no longer exploits us: we exploit ourselves while believing ourselves free, and the result is exhaustion and depression.","obras":["The Burnout Society (2010)","The Transparency Society (2012)","Psychopolitics (2014)","The Expulsion of the Other (2016)"],"fuente":"Byung-Chul Han, Praise of the Earth. A Journey into the Garden (2018)","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-grandes-preguntas"]},"chalmers":{"name":"David Chalmers","dates":"b. 1966","born":1966,"died":null,"place":"Sydney (Australia)","role":"Australian philosopher of mind","idea":"Explaining the functions of the brain is not enough to explain subjective experience: why we feel anything at all is the hard problem of consciousness.","obras":["The Conscious Mind (1996)","Reality+ (2022)"],"fuente":"Reports of the conference of the Association for the Scientific Study of Consciousness (New York, 2023), including that of Nature","tradicion":false,"block":"con","subjects":["fil"],"temas":["fil-t2","fil-metafisica","fil-grandes-preguntas"]},"bostrom":{"name":"Nick Bostrom","dates":"b. 1973","born":1973,"died":null,"place":"Helsingborg (Sweden)","role":"Swedish philosopher","idea":"If advanced civilisations can simulate worlds with conscious beings and decide to do so, we ourselves probably live in a computer simulation.","obras":["Are You Living in a Computer Simulation? (2003)","Superintelligence (2014)"],"block":"con","subjects":["fil"],"temas":["fil-metafisica"]}};
